css:
@page {
    size: A4;
    margin: 1cm;
}

.booking-print {
    font-size: 13px;
}

.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.header h1 {
    margin: 0;
    font-size: 24px;
}

.booking-number {
    font-size: 13px;
    font-weight: bold;
}

.pending-banner {
    padding: 12px;
    margin-bottom: 20px;
    border: 1px solid #cc0000;
    font-weight: bold;
    text-align: center;
}

.section {
    margin-top: 20px;
}

.section h2 {
    font-size: 16px;
    margin-bottom: 10px;
}

.info-table,
.addon-table {
    width: 100%;
    border-collapse: collapse;
}

.info-table td,
.addon-table th,
.addon-table td {
    border: 1px solid #ddd;
    padding: 8px;
}

.addon-table th {
    font-weight: bold;
    text-align: left;
}

.addon-table td:nth-child(2),
.addon-table td:nth-child(3),
.addon-table td:nth-child(4),
.addon-table th:nth-child(2),
.addon-table th:nth-child(3),
.addon-table th:nth-child(4) {
    text-align: right;
}

.total-label {
    text-align: right;
    font-weight: bold;
}

.total-value {
    font-weight: bold;
    text-align: right;
}

.grand-total {
    margin-top: 25px;
    padding: 15px;
    border-top: 2px solid #000;
    display: flex;
    justify-content: space-between;
    font-size: 20px;
    font-weight: bold;
}

.summary {
    margin-top: 20px;
    font-size: 12px;
}

@media print {
    .btn,
    button,
    input,
    select,
    textarea,
    .no-print {
        display: none !important;
    }
}
